CREATE TABLE certificates (id UUID PRIMARY KEY, certificate_number VARCHAR(80) NOT NULL UNIQUE, course_id UUID NOT NULL REFERENCES courses(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, issued_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, version BIGINT NOT NULL DEFAULT 0, UNIQUE(course_id,user_id)); CREATE INDEX idx_certificates_number ON certificates(certificate_number);